def q(qid, question, answer, requires=(), covers=''):
    return dict(id=qid, question=question, answer=answer, requires=list(requires), covers=covers or question)

def person(pid, name, age, job, info, interviews):
    return dict(id=pid, name=name, age=age, job=job, public_info=info, interviews=interviews)

def clue(eid, title, text, requires=(), kind='محضر'):
    return dict(id=eid, title=title, text=text, requires=list(requires), kind=kind)

